SELECT ?s ?cricinfo_id ?place ?place_label ?place_country_label WHERE { ?s wdt:P31 wd:Q5 ; wdt:P2697 ?cricinfo_id . ?s wdt:P19 ?place .
        OPTIONAL { ?place rdfs:label ?place_label FILTER(lang(?place_label) = "en") }
        OPTIONAL { ?place wdt:P17 ?pc . ?pc rdfs:label ?place_country_label FILTER(lang(?place_country_label) = "en") } }
        ORDER BY ?s ?cricinfo_id ?place ?place_country_label LIMIT 30000 OFFSET 0

SELECT ?s ?cricinfo_id ?prop ?value ?value_label WHERE { ?s wdt:P31 wd:Q5 ; wdt:P2697 ?cricinfo_id .
        { ?s wdt:P552 ?value . BIND("P552" AS ?prop) } UNION { ?s wdt:P741 ?value . BIND("P741" AS ?prop) }
        OPTIONAL { ?value rdfs:label ?value_label FILTER(lang(?value_label) = "en") } } ORDER BY ?s ?cricinfo_id ?prop ?value LIMIT 30000 OFFSET 0

SELECT ?s ?cricinfo_id ?amount ?unit WHERE { ?s wdt:P31 wd:Q5 ; wdt:P2697 ?cricinfo_id .
        ?s p:P2048/psv:P2048 ?n . ?n wikibase:quantityAmount ?amount ; wikibase:quantityUnit ?unit . }
        ORDER BY ?s ?cricinfo_id ?amount ?unit LIMIT 30000 OFFSET 0
